// Timeline: one entry per chapter of engine/data/chapters.json. Chapter C<N> is rendered by the scene module
// src/scenes/c<N>.ts (default export: a Scene class); a chapter whose module does not exist yet renders the
// placeholder plate. Windows: C0 starts at 0, every other chapter 0.4 s before its first word, and each ends where
// the next begins (the last at the audio's end). scripts/lib.ts chapterWindows() uses the same rule.
// OWNER: the orchestrator. Scene builders do not edit this file.
import type { TimelineEntry } from './engine/engine';
import type { SceneClass } from './engine/scene';
import type { Lyrics } from './engine/lyrics';
import type { AudioData } from './engine/audio';
import CHAPTERS from '../../data/chapters.json';

const modules = import.meta.glob<{ default: SceneClass }>('./scenes/*.ts');
const scene = (name: string) => () => {
  const m = modules[`./scenes/${name}.ts`] ?? modules['./scenes/_placeholder.ts'];
  return m!();
};

export function makeTimeline(_ly: Lyrics, au: AudioData): TimelineEntry[] {
  const E = (id: string, file: string, start: number, end: number, extra: Partial<TimelineEntry> = {}): TimelineEntry =>
    ({ id, load: scene(file), start, end, ...extra });
  const ch = CHAPTERS as unknown as { id: string; title: string; start: number; end: number }[];
  return ch.map((c, i) => {
    const start = i === 0 ? 0 : c.start - 0.4;
    const end = i + 1 < ch.length ? ch[i + 1]!.start - 0.4 : au.duration;
    const n = c.id.replace(/^C/i, '').toLowerCase();
    return E(`c${n}`, `c${n}`, start, end, { params: { title: c.title, fig: `CH. ${n}` } } as any);
  });
}
